
pageMeta.consignment=['Konsinyasi','Barang titipan, komisi, dan settlement pemilik'];
let consignmentActiveTab='items';
const consignmentNormalizedDBs=new WeakSet();
function ensureConsignmentData(){
if(consignmentNormalizedDBs.has(db))return;
if(!Array.isArray(db.consignors))db.consignors=[];
if(!Array.isArray(db.consignments))db.consignments=[];
if(!Array.isArray(db.consignmentSettlements))db.consignmentSettlements=[];
db.consignors=db.consignors.filter(x=>x&&typeof x==='object').map((x,i)=>({id:String(x.id||`OWN-${i+1}`),name:String(x.name||`Pemilik ${i+1}`),phone:String(x.phone||''),address:String(x.address||''),note:String(x.note||'')}));
db.consignments=db.consignments.filter(x=>x&&typeof x==='object').map((x,i)=>{
const id=String(x.id||`CSG-${i+1}`),receipts=(Array.isArray(x.receipts)?x.receipts:[]).filter(r=>r&&typeof r==='object').map((r,j)=>({id:String(r.id||`${id}-RCV-${j+1}`),date:r.date||x.startDate||new Date().toISOString(),qty:Math.max(0,Number(r.qty)||0)})).filter(r=>r.qty>0);
if(!receipts.length&&Number(x.qtyReceived)>0)receipts.push({id:`${id}-RCV-1`,date:x.startDate||new Date().toISOString(),qty:Math.max(0,Number(x.qtyReceived)||0)});
return{id,ownerId:String(x.ownerId||''),productId:Number(x.productId)||0,price:Math.max(0,Number(x.price)||0),commissionType:x.commissionType==='nominal'?'nominal':'percent',commissionValue:Math.max(0,Number(x.commissionValue)||0),receipts,baseStock:Math.max(0,Number(x.baseStock)||0),active:x.active!==false,endedAt:x.endedAt||null,returnedQty:Math.max(0,Number(x.returnedQty)||0),note:String(x.note||'')};
}).filter(x=>x.ownerId&&x.productId&&x.receipts.length);
db.consignmentSettlements=db.consignmentSettlements.filter(x=>x&&typeof x==='object').map((x,i)=>({id:String(x.id||`CST-${i+1}`),ownerId:String(x.ownerId||''),date:x.date||new Date().toISOString(),amount:Math.max(0,Number(x.amount)||0),method:String(x.method||'Tunai'),note:String(x.note||''),cashEntryId:String(x.cashEntryId||'')})).filter(x=>x.ownerId&&x.amount>0);
consignmentNormalizedDBs.add(db);
}
function getConsignor(id){ensureConsignmentData();return db.consignors.find(x=>String(x.id)===String(id))||null}
function getConsignment(id){ensureConsignmentData();return db.consignments.find(x=>String(x.id)===String(id))||null}
function activeConsignmentForProduct(productId,exceptId=''){ensureConsignmentData();return db.consignments.find(x=>x.active!==false&&Number(x.productId)===Number(productId)&&String(x.id)!==String(exceptId))||null}
function consignmentStartDate(c){const rows=(c?.receipts||[]).map(r=>new Date(r.date)).filter(d=>!Number.isNaN(d.getTime())).sort((a,b)=>a-b);return rows[0]||new Date()}
function consignmentSalesMetrics(c){
ensureConsignmentData();if(!c)return{received:0,soldQty:0,revenue:0,commission:0,ownerDue:0,remaining:0,returned:0};
const receipts=(c.receipts||[]).map(r=>({type:'receipt',date:new Date(r.date),qty:Math.max(0,Number(r.qty)||0),order:0})).filter(e=>!Number.isNaN(e.date.getTime())&&e.qty>0);
const first=consignmentStartDate(c).getTime(),end=c.endedAt?new Date(c.endedAt).getTime():Infinity,sales=[];
(db.sales||[]).filter(validSale).forEach(s=>{const t=new Date(s.date).getTime();if(!Number.isFinite(t)||t<first||t>end)return;(s.items||[]).forEach(it=>{if(Number(it.productId)!==Number(c.productId))return;const qty=Math.max(0,Number(it.qty)||0);if(qty>0)sales.push({type:'sale',date:new Date(s.date),qty,price:Math.max(0,Number(it.price)||0),saleId:String(s.id||''),order:1})})});
const events=[...receipts,...sales].sort((a,b)=>a.date-b.date||a.order-b.order),received=sum(receipts,x=>x.qty);let available=0,ownAvailable=Math.max(0,Number(c.baseStock)||0),soldQty=0,revenue=0;
events.forEach(e=>{if(e.type==='receipt'){available+=e.qty;return}const ownTake=Math.min(ownAvailable,e.qty);ownAvailable-=ownTake;const take=Math.min(available,Math.max(0,e.qty-ownTake));if(take<=0)return;available-=take;soldQty+=take;revenue+=take*e.price});
const returned=Math.min(Math.max(0,Number(c.returnedQty)||0),available),remaining=Math.max(0,available-returned);let commission=c.commissionType==='nominal'?soldQty*Math.max(0,Number(c.commissionValue)||0):revenue*(Math.max(0,Number(c.commissionValue)||0)/100);commission=Math.min(revenue,Math.max(0,commission));
return{received,soldQty,revenue,commission,ownerDue:Math.max(0,revenue-commission),remaining,returned};
}
function consignmentOwnerMetrics(ownerId){
ensureConsignmentData();const items=db.consignments.filter(c=>String(c.ownerId)===String(ownerId)),metrics=items.map(consignmentSalesMetrics),settlements=db.consignmentSettlements.filter(x=>String(x.ownerId)===String(ownerId)),due=sum(metrics,m=>m.ownerDue),settled=sum(settlements,x=>Number(x.amount)||0);return{items,received:sum(metrics,m=>m.received),soldQty:sum(metrics,m=>m.soldQty),revenue:sum(metrics,m=>m.revenue),commission:sum(metrics,m=>m.commission),due,settled,outstanding:Math.max(0,due-settled),settlements}
}
function consignmentTotals(){ensureConsignmentData();const owners=db.consignors.map(o=>consignmentOwnerMetrics(o.id));return{owners:db.consignors.length,active:db.consignments.filter(c=>c.active!==false).length,soldQty:sum(db.consignments,c=>consignmentSalesMetrics(c).soldQty),outstanding:sum(owners,m=>m.outstanding)}}
function consignmentCommissionLabel(c){return c.commissionType==='nominal'?`${rupiah(c.commissionValue)} / item`:`${Number(c.commissionValue||0).toLocaleString('id-ID',{maximumFractionDigits:2})}% dari penjualan`}
function setConsignmentTab(tab){consignmentActiveTab=['owners','items','settlements'].includes(tab)?tab:'items';renderConsignmentPage()}
function openConsignmentPage(){ensureConsignmentData();go('consignment');if(!document.getElementById('screen-consignment')?.classList.contains('active'))return;document.querySelectorAll('[data-screen="more"]').forEach(el=>{el.classList.add('active');if(el.classList.contains('mbtn'))el.setAttribute('aria-current','page')})}
function consignmentSummaryHTML(){const t=consignmentTotals();return`<div class="consignment-summary-grid"><div class="consignment-summary-card"><small>Pemilik Barang</small><b>${t.owners.toLocaleString('id-ID')}</b></div><div class="consignment-summary-card"><small>Barang Aktif</small><b>${t.active.toLocaleString('id-ID')}</b></div><div class="consignment-summary-card"><small>Terjual / Keluar</small><b>${t.soldQty.toLocaleString('id-ID',{maximumFractionDigits:2})}</b></div><div class="consignment-summary-card due"><small>Belum Disetor</small><b>${rupiah(t.outstanding)}</b></div></div>`}
function renderConsignmentPage(){
ensureConsignmentData();const root=document.getElementById('consignmentBody');if(!root)return;
root.innerHTML=`<div class="consignment-guide"><div class="consignment-guide-icon">◇</div><div><b>Alur Konsinyasi</b><small>1. Tambah pemilik barang → 2. Tambah barang titipan → 3. Jual seperti biasa di Kasir → 4. Bayar hak pemilik melalui Settlement.</small></div></div>${consignmentSummaryHTML()}<div class="consignment-tabs" role="tablist"><button class="consignment-tab ${consignmentActiveTab==='items'?'active':''}" type="button" onclick="setConsignmentTab('items')">Barang Titipan</button><button class="consignment-tab ${consignmentActiveTab==='owners'?'active':''}" type="button" onclick="setConsignmentTab('owners')">Pemilik</button><button class="consignment-tab ${consignmentActiveTab==='settlements'?'active':''}" type="button" onclick="setConsignmentTab('settlements')">Settlement</button></div><div id="consignmentPanel" class="consignment-panel"></div>`;
renderConsignmentPanel();
}
function renderConsignmentPanel(){const panel=document.getElementById('consignmentPanel');if(!panel)return;if(consignmentActiveTab==='owners')renderConsignmentOwners(panel);else if(consignmentActiveTab==='settlements')renderConsignmentSettlements(panel);else renderConsignmentItems(panel)}
let consignmentInlineAddOpen=false;
function consignmentInlineAddAvailable(){return(db.products||[]).filter(p=>!p.noStock&&!activeConsignmentForProduct(p.id))}
function consignmentInlineProductListHTML(selectedProduct){
const rows=consignmentInlineAddAvailable();
return rows.map(p=>{const pid=Number(p.id)||0,active=pid===Number(selectedProduct),search=`${p.name||''} ${p.barcode||''} ${p.sku||''} ${p.category||''}`.toLocaleLowerCase('id-ID');return`<button class="consignment-inline-product-card ${active?'active':''}" type="button" data-product-id="${pid}" data-product-search="${esc(search)}" aria-pressed="${active?'true':'false'}" onclick="selectConsignmentInlineProduct(${pid})"><span class="consignment-inline-product-main"><b>${esc(p.name||'Produk')}</b><small>${esc(p.barcode||p.sku||p.category||'Tanpa barcode')}</small></span><span class="consignment-inline-product-value"><small>Stok ${Number(p.stock||0).toLocaleString('id-ID',{maximumFractionDigits:2})} ${esc(p.unit||'pcs')}</small><b>${rupiah(p.price||0)}</b></span><i aria-hidden="true">✓</i></button>`}).join('')
}
function selectConsignmentInlineProduct(id){
const input=document.getElementById('consignmentProduct');if(input)input.value=String(id);
document.querySelectorAll('#consignmentInlineProductList .consignment-inline-product-card').forEach(btn=>{const active=String(btn.dataset.productId)===String(id);btn.classList.toggle('active',active);btn.setAttribute('aria-pressed',String(active))});
syncConsignmentProductPrice();
}
function filterConsignmentInlineProducts(){
const q=String(document.getElementById('consignmentInlineProductSearch')?.value||'').trim().toLocaleLowerCase('id-ID');
document.querySelectorAll('#consignmentInlineProductList .consignment-inline-product-card').forEach(btn=>{btn.hidden=!!q&&!String(btn.dataset.productSearch||'').includes(q)})
}
function consignmentInlineAddHTML(){
const available=consignmentInlineAddAvailable(),selectedProduct=available[0]?.id||0,p=getProduct(Number(selectedProduct));
return`<div class="consignment-inline-form" id="consignmentInlineAddForm"><div class="consignment-inline-form-head"><div><b>Tambah Barang Titipan</b><small>Pilih produk langsung dari daftar di halaman ini.</small></div><button class="consignment-inline-form-close" type="button" aria-label="Tutup form" onclick="closeConsignmentInlineAdd()">×</button></div><div class="consignment-inline-grid"><div class="field"><label>Pemilik Barang</label><select id="consignmentOwner">${db.consignors.map(o=>`<option value="${esc(o.id)}">${esc(o.name)}</option>`).join('')}</select></div><div class="field full consignment-inline-product"><label>Pilih Produk</label><input id="consignmentProduct" type="hidden" value="${Number(selectedProduct)||0}"><div class="consignment-inline-product-picker"><div class="consignment-inline-product-search"><input id="consignmentInlineProductSearch" type="search" autocomplete="off" placeholder="Cari nama / barcode / SKU..." oninput="filterConsignmentInlineProducts()"></div><div class="consignment-inline-product-list" id="consignmentInlineProductList">${consignmentInlineProductListHTML(selectedProduct)}</div></div><small class="consignment-inline-product-help">Sentuh produk untuk memilih. Produk aktif konsinyasi tidak ditampilkan.</small></div><div class="field"><label>Stok Titipan Masuk</label><input id="consignmentQty" type="number" inputmode="decimal" min="0.01" step="0.01" value="1"></div><div class="field"><label>Tanggal Masuk</label><input id="consignmentDate" type="date" value="${todayKey()}"></div><div class="field"><label>Harga Jual</label><input id="consignmentPrice" class="nominal-input" inputmode="numeric" value="${nominal(p?.price||0)}"></div><div class="field"><label>Jenis Komisi Toko</label><select id="consignmentCommissionType"><option value="percent">Persentase dari Penjualan</option><option value="nominal">Nominal per Item</option></select></div><div class="field"><label>Nilai Komisi</label><input id="consignmentCommissionValue" type="number" inputmode="decimal" min="0" step="0.01" value="10"></div><div class="field full"><label>Catatan</label><textarea id="consignmentNote" placeholder="Opsional"></textarea></div></div><div class="consignment-form-note">Harga jual mengikuti produk yang dipilih dan tetap dapat diubah sebelum disimpan. Komisi dihitung dari penjualan aktual di Kasir.</div><div class="consignment-inline-actions"><button class="btn" type="button" onclick="closeConsignmentInlineAdd()">Batal</button><button class="btn btn-primary" type="button" onclick="saveConsignmentItem('')">Simpan Barang Titipan</button></div></div>`
}
function openConsignmentInlineAdd(){
ensureConsignmentData();if(!db.consignors.length)return openConsignorModal();if(!consignmentInlineAddAvailable().length)return toast('Tidak ada produk yang tersedia. Tambahkan produk baru atau akhiri konsinyasi aktif terlebih dahulu.','error');consignmentInlineAddOpen=true;renderConsignmentPanel();setTimeout(()=>document.getElementById('consignmentInlineAddForm')?.scrollIntoView({behavior:'smooth',block:'start'}),40)
}
function closeConsignmentInlineAdd(){consignmentInlineAddOpen=false;renderConsignmentPanel()}
function renderConsignmentItems(panel){
const rows=[...db.consignments].sort((a,b)=>(b.active!==false)-(a.active!==false)||consignmentStartDate(b)-consignmentStartDate(a));
panel.innerHTML=`<div class="consignment-panel-head"><div class="consignment-panel-copy"><b>Barang Titipan</b><small>Produk titipan yang stok dan penjualannya dipantau otomatis.</small></div><button class="btn btn-primary" type="button" onclick="openConsignmentInlineAdd()" ${consignmentInlineAddOpen?'disabled':''}>+ Barang Titipan</button></div>${consignmentInlineAddOpen?consignmentInlineAddHTML():''}${rows.length?`<div class="consignment-search"><input id="consignmentItemSearch" type="search" autocomplete="off" placeholder="Cari produk / pemilik..." oninput="filterConsignmentItemCards()"></div><div class="consignment-list" id="consignmentItemList">${rows.map(consignmentItemCardHTML).join('')}</div>`:`${consignmentInlineAddOpen?'':`<div class="consignment-empty"><b>Belum ada barang titipan</b><span>Tambahkan pemilik terlebih dahulu, lalu pilih produk yang dititipkan.</span><button class="btn btn-primary" type="button" onclick="${db.consignors.length?'openConsignmentInlineAdd()':'openConsignorModal()'}">${db.consignors.length?'+ Barang Titipan':'+ Pemilik Barang'}</button></div>`}`}`
}
function consignmentItemCardHTML(c){const p=getProduct(c.productId),o=getConsignor(c.ownerId),m=consignmentSalesMetrics(c),search=`${p?.name||''} ${p?.barcode||''} ${o?.name||''}`.toLocaleLowerCase('id-ID');return`<article class="consignment-card" data-consignment-search="${esc(search)}"><div class="consignment-card-head"><div class="consignment-card-title"><b>${esc(p?.name||'Produk tidak ditemukan')}</b><small>${esc(o?.name||'Pemilik tidak ditemukan')}${p?.barcode?` • ${esc(p.barcode)}`:''}</small></div><span class="consignment-status ${c.active!==false?'active':'closed'}">${c.active!==false?'Aktif':'Selesai'}</span></div><div class="consignment-metrics consignment-product-metrics"><div class="consignment-metric"><span>Stok Titipan</span><b>${m.remaining.toLocaleString('id-ID',{maximumFractionDigits:2})} ${esc(p?.unit||'pcs')}</b></div><div class="consignment-metric"><span>Terjual</span><b>${m.soldQty.toLocaleString('id-ID',{maximumFractionDigits:2})}</b></div><div class="consignment-metric"><span>Omzet</span><b>${rupiah(m.revenue)}</b></div><div class="consignment-metric"><span>Total Masuk</span><b>${m.received.toLocaleString('id-ID',{maximumFractionDigits:2})}</b></div><div class="consignment-metric due"><span>Hak Pemilik</span><b>${rupiah(m.ownerDue)}</b></div><div class="consignment-metric"><span>Komisi Toko</span><b>${rupiah(m.commission)}</b></div></div><div class="consignment-commission-row"><span>Skema komisi</span><b>${esc(consignmentCommissionLabel(c))}</b></div><div class="consignment-actions">${c.active!==false?`<button type="button" onclick="openConsignmentItemModal('${esc(c.id)}')">Edit</button><button class="primary" type="button" onclick="openConsignmentReceiptModal('${esc(c.id)}')">+ Stok Titipan</button><button class="danger" type="button" onclick="closeConsignmentItem('${esc(c.id)}')">Akhiri</button>`:`<button type="button" onclick="openConsignmentDetail('${esc(c.id)}')">Detail</button>`}</div></article>`}
function filterConsignmentItemCards(){const q=String(document.getElementById('consignmentItemSearch')?.value||'').trim().toLocaleLowerCase('id-ID');document.querySelectorAll('#consignmentItemList [data-consignment-search]').forEach(el=>{el.hidden=!!q&&!String(el.dataset.consignmentSearch||'').includes(q)})}
function renderConsignmentOwners(panel){
const rows=[...db.consignors].sort((a,b)=>String(a.name).localeCompare(String(b.name),'id'));
panel.innerHTML=`<div class="consignment-panel-head consignment-owner-panel-head"><div class="consignment-panel-copy"><b>Pemilik Barang</b><small>Kelola penitip dan saldo konsinyasi yang belum disetor.</small></div><button class="btn btn-primary" type="button" onclick="openConsignorModal()">+ Pemilik</button></div><div class="consignment-list consignment-owner-list">${rows.length?rows.map(o=>{const m=consignmentOwnerMetrics(o.id),initial=String(o.name||'P').trim().charAt(0).toUpperCase()||'P',activeItems=m.items.filter(x=>x.active!==false).length;return`<article class="consignment-card consignment-owner-card"><div class="consignment-owner-head"><div class="consignment-owner-avatar">${esc(initial)}</div><div class="consignment-owner-identity"><b>${esc(o.name)}</b><span>${esc(o.phone||'WhatsApp belum diisi')}</span>${o.address?`<small>${esc(o.address)}</small>`:''}</div><span class="consignment-status ${m.outstanding>0?'active':'closed'}">${m.outstanding>0?'Ada Saldo':'Lunas'}</span></div><div class="consignment-owner-balance ${m.outstanding>0?'has-due':'is-clear'}"><div><small>Belum Disetor</small><strong>${rupiah(m.outstanding)}</strong></div><span>${m.outstanding>0?'Perlu settlement':'Sudah lunas'}</span></div><div class="consignment-owner-stats"><div><small>Barang Titipan</small><b>${m.items.length} produk</b><span>${activeItems} aktif</span></div><div><small>Terjual</small><b>${m.soldQty.toLocaleString('id-ID',{maximumFractionDigits:2})}</b><span>item</span></div><div><small>Omzet</small><b>${rupiah(m.revenue)}</b><span>penjualan</span></div></div><div class="consignment-actions consignment-owner-actions">${m.outstanding>0?`<button class="primary" type="button" onclick="openConsignmentSettlementModal('${esc(o.id)}')">Bayar Pemilik</button>`:''}<button type="button" onclick="openConsignorModal('${esc(o.id)}')">Edit Pemilik</button></div></article>`}).join(''):`<div class="consignment-empty"><b>Belum ada pemilik barang</b><span>Tambahkan data penitip sebelum mencatat barang konsinyasi.</span><button class="btn btn-primary" type="button" onclick="openConsignorModal()">+ Pemilik Barang</button></div>`}</div>`
}
function renderConsignmentSettlements(panel){
const rows=[...db.consignmentSettlements].sort((a,b)=>new Date(b.date)-new Date(a.date)),payableOwners=db.consignors.filter(o=>consignmentOwnerMetrics(o.id).outstanding>0);panel.innerHTML=`<div class="consignment-panel-head"><div class="consignment-panel-copy"><b>Settlement Pemilik</b><small>Catatan pembayaran hak pemilik dari barang yang sudah terjual.</small></div><button class="btn btn-primary" type="button" onclick="openConsignmentSettlementModal()" ${payableOwners.length?'':'disabled'}>+ Bayar</button></div><div class="consignment-list">${rows.length?rows.map(x=>{const o=getConsignor(x.ownerId);return`<div class="consignment-settlement-row"><div class="consignment-settlement-main"><b>${esc(o?.name||'Pemilik')}</b><small>${fmtTime(x.date)} • ${esc(x.method)}${x.note?` • ${esc(x.note)}`:''}</small></div><div class="consignment-settlement-value"><b>${rupiah(x.amount)}</b><button type="button" onclick="deleteConsignmentSettlement('${esc(x.id)}')">Hapus</button></div></div>`}).join(''):`<div class="consignment-empty"><b>Belum ada settlement</b><span>Setelah barang konsinyasi terjual, bayar hak pemilik dari menu ini.</span></div>`}</div>`
}
function openConsignorModal(id=''){
ensureConsignmentData();const o=id?getConsignor(id):null;showModal(o?'Edit Pemilik Barang':'Tambah Pemilik Barang',o?.name||'Data orang / pemasok yang menitipkan barang.',`<div class="consignment-modal-grid"><div class="field full"><label>Nama Pemilik</label><input id="consignorName" value="${esc(o?.name||'')}" placeholder="Nama pemilik barang"></div><div class="field"><label>WhatsApp</label><input id="consignorPhone" inputmode="tel" value="${esc(o?.phone||'')}" placeholder="08xxxxxxxxxx"></div><div class="field"><label>Kota / Alamat</label><input id="consignorAddress" value="${esc(o?.address||'')}" placeholder="Alamat pemilik"></div><div class="field full"><label>Catatan</label><textarea id="consignorNote" placeholder="Opsional">${esc(o?.note||'')}</textarea></div></div>`,[{label:'Batal',close:true},...(o?[{label:'Hapus',danger:true,fn:()=>deleteConsignor(o.id)}]:[]),{label:'Simpan',primary:true,fn:()=>saveConsignor(o?.id||'')}],true);document.getElementById('modalBox')?.classList.add('consignment-modal')
}
function saveConsignor(id=''){const name=String(document.getElementById('consignorName')?.value||'').trim();if(!name)return toast('Nama pemilik wajib diisi.','error');const data={name,phone:String(document.getElementById('consignorPhone')?.value||'').trim(),address:String(document.getElementById('consignorAddress')?.value||'').trim(),note:String(document.getElementById('consignorNote')?.value||'').trim()};const o=id?getConsignor(id):null;if(o)Object.assign(o,data);else db.consignors.push({id:uid('OWN'),...data});save();closeModal();renderConsignmentPage();toast('Data pemilik disimpan.')}
function deleteConsignor(id){if(db.consignments.some(c=>String(c.ownerId)===String(id)))return toast('Pemilik masih memiliki riwayat barang konsinyasi dan tidak dapat dihapus.','error');if(!confirm('Hapus data pemilik ini?'))return;db.consignors=db.consignors.filter(x=>String(x.id)!==String(id));save();closeModal();renderConsignmentPage();toast('Data pemilik dihapus.')}
function consignmentProductOptions(selected=0){const rows=(db.products||[]).filter(p=>!p.noStock&&(!activeConsignmentForProduct(p.id)||Number(p.id)===Number(selected)));return rows.map(p=>`<option value="${p.id}" ${Number(p.id)===Number(selected)?'selected':''}>${esc(p.name)} • stok ${Number(p.stock||0).toLocaleString('id-ID',{maximumFractionDigits:2})}</option>`).join('')}
function syncConsignmentProductPrice(){const p=getProduct(Number(document.getElementById('consignmentProduct')?.value));const inp=document.getElementById('consignmentPrice');if(p&&inp)setNominalInput(inp,p.price||0)}
function openConsignmentItemModal(id=''){
if(!id)return openConsignmentInlineAdd();
ensureConsignmentData();if(!db.consignors.length)return openConsignorModal();const c=id?getConsignment(id):null,available=(db.products||[]).filter(p=>!p.noStock&&(!activeConsignmentForProduct(p.id,c?.id)||Number(p.id)===Number(c?.productId)));if(!available.length&&!c)return toast('Tidak ada produk yang tersedia. Tambahkan produk baru atau akhiri konsinyasi aktif terlebih dahulu.','error');const selectedProduct=c?.productId||available[0]?.id||0,p=getProduct(Number(selectedProduct)),first=consignmentStartDate(c||{receipts:[{date:new Date().toISOString()}]}),dateValue=dateKey(first);
showModal(c?'Edit Barang Titipan':'Tambah Barang Titipan',c?getProduct(c.productId)?.name||'Konsinyasi':'Pilih pemilik, produk, stok masuk, dan komisi.',`<div class="consignment-modal-grid"><div class="field"><label>Pemilik Barang</label><select id="consignmentOwner" ${c?'disabled':''}>${db.consignors.map(o=>`<option value="${esc(o.id)}" ${String(o.id)===String(c?.ownerId)?'selected':''}>${esc(o.name)}</option>`).join('')}</select></div><div class="field"><label>Produk</label><select id="consignmentProduct" ${c?'disabled':''} onchange="syncConsignmentProductPrice()">${consignmentProductOptions(selectedProduct)}</select></div>${c?`<div class="field"><label>Total Barang Masuk</label><input value="${consignmentSalesMetrics(c).received.toLocaleString('id-ID',{maximumFractionDigits:2})}" disabled></div><div class="field"><label>Tanggal Mulai</label><input value="${fmtDate(first)}" disabled></div>`:`<div class="field"><label>Stok Titipan Masuk</label><input id="consignmentQty" type="number" inputmode="decimal" min="0.01" step="0.01" value="1"></div><div class="field"><label>Tanggal Masuk</label><input id="consignmentDate" type="date" value="${dateValue}"></div>`}<div class="field"><label>Harga Jual</label><input id="consignmentPrice" class="nominal-input" inputmode="numeric" value="${nominal(c?.price||p?.price||0)}"></div><div class="field"><label>Jenis Komisi Toko</label><select id="consignmentCommissionType"><option value="percent" ${c?.commissionType!=='nominal'?'selected':''}>Persentase dari Penjualan</option><option value="nominal" ${c?.commissionType==='nominal'?'selected':''}>Nominal per Item</option></select></div><div class="field"><label>Nilai Komisi</label><input id="consignmentCommissionValue" type="number" inputmode="decimal" min="0" step="0.01" value="${Number(c?.commissionValue||10)}"></div><div class="field full"><label>Catatan</label><textarea id="consignmentNote" placeholder="Opsional">${esc(c?.note||'')}</textarea></div></div><div class="consignment-form-note">Harga jual akan digunakan sebagai harga produk saat disimpan. Komisi dihitung dari nilai penjualan aktual di Kasir.</div>`,[{label:'Batal',close:true},{label:c?'Simpan Perubahan':'Simpan Barang',primary:true,fn:()=>saveConsignmentItem(c?.id||'')}],true);const _consignmentItemModalBox=document.getElementById('modalBox');_consignmentItemModalBox?.classList.add('consignment-modal');if(c)_consignmentItemModalBox?.classList.add('consignment-item-edit-modal')
}
function saveConsignmentItem(id=''){
ensureConsignmentData();const existing=id?getConsignment(id):null,ownerId=existing?.ownerId||String(document.getElementById('consignmentOwner')?.value||''),productId=existing?.productId||Number(document.getElementById('consignmentProduct')?.value),p=getProduct(Number(productId)),price=Math.max(0,parseNominal(document.getElementById('consignmentPrice')?.value)),commissionType=document.getElementById('consignmentCommissionType')?.value==='nominal'?'nominal':'percent',commissionValue=Math.max(0,Number(document.getElementById('consignmentCommissionValue')?.value)||0),note=String(document.getElementById('consignmentNote')?.value||'').trim();if(!getConsignor(ownerId))return toast('Pilih pemilik barang.','error');if(!p)return toast('Pilih produk.','error');if(price<=0)return toast('Harga jual wajib diisi.','error');if(commissionType==='percent'&&commissionValue>100)return toast('Komisi persentase maksimal 100%.','error');
if(existing){existing.price=price;existing.commissionType=commissionType;existing.commissionValue=commissionValue;existing.note=note;p.price=price}else{if(activeConsignmentForProduct(productId))return toast('Produk sudah berada pada konsinyasi aktif.','error');const qty=Math.max(0,Number(document.getElementById('consignmentQty')?.value)||0);if(qty<=0)return toast('Stok titipan masuk wajib lebih dari 0.','error');const d=String(document.getElementById('consignmentDate')?.value||todayKey()),date=localDateISO(d);if(!date)return toast('Tanggal masuk konsinyasi tidak valid.','error');const cid=uid('CSG'),baseStock=Math.max(0,Number(p.stock)||0);db.consignments.push({id:cid,ownerId,productId:Number(productId),price,commissionType,commissionValue,receipts:[{id:uid('RCV'),date,qty}],baseStock,active:true,endedAt:null,returnedQty:0,note});p.stock=baseStock+qty;p.price=price}
if(existing)closeModal();else consignmentInlineAddOpen=false;save();renderStock();renderProducts();renderConsignmentPage();toast(existing?'Pengaturan konsinyasi diperbarui.':'Barang titipan ditambahkan.')
}
function openConsignmentReceiptModal(id){const c=getConsignment(id);if(!c||c.active===false)return toast('Konsinyasi sudah selesai.','error');const p=getProduct(c.productId);showModal('+ Stok Titipan',p?.name||'Produk','<div class="consignment-modal-grid"><div class="field"><label>Jumlah Masuk</label><input id="consignmentReceiptQty" type="number" inputmode="decimal" min="0.01" step="0.01" value="1"></div><div class="field"><label>Tanggal Masuk</label><input id="consignmentReceiptDate" type="date" value="'+todayKey()+'"></div></div>',[{label:'Batal',close:true},{label:'Tambah Stok',primary:true,fn:()=>saveConsignmentReceipt(id)}]);document.getElementById('modalBox')?.classList.add('consignment-modal')}
function saveConsignmentReceipt(id){const c=getConsignment(id),p=c?getProduct(c.productId):null,qty=Math.max(0,Number(document.getElementById('consignmentReceiptQty')?.value)||0);if(!c||!p||c.active===false)return toast('Konsinyasi tidak aktif.','error');if(qty<=0)return toast('Jumlah stok wajib lebih dari 0.','error');const d=String(document.getElementById('consignmentReceiptDate')?.value||todayKey()),date=localDateISO(d);if(!date)return toast('Tanggal stok titipan tidak valid.','error');c.receipts.push({id:uid('RCV'),date,qty});p.stock=Math.max(0,Number(p.stock)||0)+qty;save();closeModal();renderStock();renderConsignmentPage();toast('Stok titipan ditambahkan.')}
function openConsignmentDetail(id){const c=getConsignment(id),p=c?getProduct(c.productId):null,o=c?getConsignor(c.ownerId):null;if(!c)return;const m=consignmentSalesMetrics(c);showModal('Detail Konsinyasi',p?.name||'Barang Titipan',`<div class="consignment-settlement-summary"><div><small>Pemilik</small><b>${esc(o?.name||'-')}</b></div><div><small>Status</small><b>${c.active!==false?'Aktif':'Selesai'}</b></div><div><small>Total Masuk</small><b>${m.received.toLocaleString('id-ID',{maximumFractionDigits:2})}</b></div><div><small>Terjual</small><b>${m.soldQty.toLocaleString('id-ID',{maximumFractionDigits:2})}</b></div><div><small>Omzet</small><b>${rupiah(m.revenue)}</b></div><div class="due"><small>Hak Pemilik</small><b>${rupiah(m.ownerDue)}</b></div></div><div class="consignment-form-note">Komisi toko: ${esc(consignmentCommissionLabel(c))} • ${rupiah(m.commission)}${m.returned?` • Dikembalikan ${m.returned.toLocaleString('id-ID',{maximumFractionDigits:2})} item`:''}</div>`,[{label:'Tutup',close:true}],true)}
function closeConsignmentItem(id){const c=getConsignment(id),p=c?getProduct(c.productId):null;if(!c||c.active===false)return;const m=consignmentSalesMetrics(c),msg=m.remaining>0?`Akhiri konsinyasi dan kembalikan sisa ${m.remaining.toLocaleString('id-ID',{maximumFractionDigits:2})} ${p?.unit||'item'} ke pemilik?`:'Akhiri konsinyasi ini?';if(!confirm(msg))return;c.active=false;c.endedAt=new Date().toISOString();c.returnedQty=Math.max(0,Number(c.returnedQty)||0)+m.remaining;if(p&&!p.noStock&&m.remaining>0)p.stock=Math.max(0,(Number(p.stock)||0)-m.remaining);save();renderStock();renderConsignmentPage();toast('Konsinyasi diakhiri.')}
function payableConsignorOptions(selected=''){return db.consignors.map(o=>({o,m:consignmentOwnerMetrics(o.id)})).filter(x=>x.m.outstanding>0).map(({o,m})=>`<option value="${esc(o.id)}" ${String(o.id)===String(selected)?'selected':''}>${esc(o.name)} • ${rupiah(m.outstanding)}</option>`).join('')}
function syncConsignmentSettlementOwner(){const ownerId=String(document.getElementById('consignmentSettlementOwner')?.value||''),m=consignmentOwnerMetrics(ownerId),amount=document.getElementById('consignmentSettlementAmount'),due=document.getElementById('consignmentSettlementDue');if(amount)setNominalInput(amount,m.outstanding);if(due)due.textContent=rupiah(m.outstanding)}
function openConsignmentSettlementModal(ownerId=''){ensureConsignmentData();const candidates=db.consignors.filter(o=>consignmentOwnerMetrics(o.id).outstanding>0);if(!candidates.length)return toast('Belum ada saldo konsinyasi yang perlu dibayar.');const selected=candidates.some(o=>String(o.id)===String(ownerId))?String(ownerId):String(candidates[0].id),m=consignmentOwnerMetrics(selected);showModal('Bayar Settlement','Bayar hak pemilik dari barang konsinyasi yang sudah terjual.',`<div class="consignment-settlement-summary"><div><small>Total Hak Pemilik</small><b>${rupiah(m.due)}</b></div><div class="due"><small>Belum Disetor</small><b id="consignmentSettlementDue">${rupiah(m.outstanding)}</b></div></div><div class="consignment-modal-grid"><div class="field full"><label>Pemilik Barang</label><select id="consignmentSettlementOwner" onchange="syncConsignmentSettlementOwner()">${payableConsignorOptions(selected)}</select></div><div class="field"><label>Jumlah Bayar</label><input id="consignmentSettlementAmount" class="nominal-input" inputmode="numeric" value="${nominal(m.outstanding)}"></div><div class="field"><label>Metode</label><select id="consignmentSettlementMethod"><option>Tunai</option><option>Transfer</option></select></div><div class="field"><label>Tanggal</label><input id="consignmentSettlementDate" type="date" value="${todayKey()}"></div><div class="field full"><label>Catatan</label><input id="consignmentSettlementNote" placeholder="Contoh: Settlement minggu pertama"></div></div>`,[{label:'Batal',close:true},{label:'Bayar Pemilik',primary:true,fn:()=>saveConsignmentSettlement()}],true);document.getElementById('modalBox')?.classList.add('consignment-modal')}
function saveConsignmentSettlement(){const ownerId=String(document.getElementById('consignmentSettlementOwner')?.value||''),o=getConsignor(ownerId),m=consignmentOwnerMetrics(ownerId),amount=Math.max(0,parseNominal(document.getElementById('consignmentSettlementAmount')?.value)),method=String(document.getElementById('consignmentSettlementMethod')?.value||'Tunai'),d=String(document.getElementById('consignmentSettlementDate')?.value||todayKey()),date=localDateISO(d),note=String(document.getElementById('consignmentSettlementNote')?.value||'').trim();if(!o)return toast('Pilih pemilik barang.','error');if(!date)return toast('Tanggal settlement tidak valid.','error');if(amount<=0)return toast('Jumlah pembayaran wajib lebih dari 0.','error');if(amount>m.outstanding+0.01)return toast('Jumlah pembayaran melebihi saldo yang belum disetor.','error');const id=uid('CST'),cashEntryId=uid('CASH');db.consignmentSettlements.push({id,ownerId,date,amount,method,note,cashEntryId});if(!Array.isArray(db.cashEntries))db.cashEntries=[];db.cashEntries.push({id:cashEntryId,date,direction:'out',category:'Settlement Konsinyasi',note:`Settlement ${o.name}${note?' • '+note:''}`,method,amount,source:'consignment',sourceId:id});save();closeModal();renderConsignmentPage();renderReports();toast('Settlement pemilik dicatat.')}
function deleteConsignmentSettlement(id){const x=db.consignmentSettlements.find(s=>String(s.id)===String(id));if(!x||!confirm('Hapus catatan settlement ini?'))return;db.consignmentSettlements=db.consignmentSettlements.filter(s=>String(s.id)!==String(id));db.cashEntries=(db.cashEntries||[]).filter(c=>String(c.id)!==String(x.cashEntryId)&&!(c.source==='consignment'&&String(c.sourceId)===String(id)));save();renderConsignmentPage();renderReports();toast('Settlement dihapus.')}
